, u as (update public.products p set price_wholesale = c.atacado::numeric, updated_at = now() from c
        where p.code = c.code and (c.fonte = 'catalogo' or (p.price > 0 and c.atacado::numeric between p.price * 0.70 and p.price)) returning c.fonte)
select (select count(*) from u where fonte = 'catalogo') do_catalogo, (select count(*) from u where fonte = 'planilha') da_planilha,
  (select count(*) from public.products where price_wholesale is null) sem_atacado;
